from tools.mcptester.mcptester.scenarios.base import BaseScenario, TestCase

class PatternsScenario(BaseScenario):
    name = 'patterns'
    description = 'Pattern management tools'

    def get_test_cases(self) -> list[TestCase]:
        return [TestCase(name='list_patterns_default', tool='list_patterns', params={}, expected={'json_valid': True, 'error': False, 'contains_keys': ['patterns', 'total']}, description='List all 3 fixture patterns'), TestCase(name='list_patterns_all', tool='list_patterns', params={'active_only': False}, expected={'json_valid': True, 'error': False, 'contains_keys': ['patterns', 'total']}, description='List all patterns including inactive'), TestCase(name='list_patterns_high_confidence', tool='list_patterns', params={'min_confidence': 0.8}, expected={'json_valid': True, 'error': False, 'contains_keys': ['patterns']}, description='List patterns with confidence >= 0.8'), TestCase(name='list_patterns_frequently_seen', tool='list_patterns', params={'min_times_seen': 20}, expected={'json_valid': True, 'error': False, 'contains_keys': ['patterns']}, description='List patterns seen >= 20 times'), TestCase(name='list_patterns_paginated', tool='list_patterns', params={'limit': 2, 'offset': 0}, expected={'json_valid': True, 'error': False, 'contains_keys': ['patterns', 'total', 'limit', 'offset']}, description='List patterns with pagination'), TestCase(name='get_pattern_existing', tool='get_pattern', params={'pattern_id': 'pat_001'}, expected={'exact_values': {'id': 'pat_001'}, 'contains_keys': ['signature_function', 'pattern_confidence', 'times_seen']}, description='Get existing pattern by ID'), TestCase(name='get_pattern_not_found', tool='get_pattern', params={'pattern_id': 'nonexistent_pattern'}, expected={'contains_keys': ['error']}, description='Get non-existent pattern returns error'), TestCase(name='get_pattern_statistics', tool='get_pattern_statistics', params={}, expected={'json_valid': True, 'error': False, 'contains_keys': ['total_patterns', 'active_patterns']}, description='Get aggregate pattern statistics'), TestCase(name='get_pattern_root_causes_existing', tool='get_pattern_root_causes', params={'pattern_id': 'pat_001'}, expected={'is_array': True, 'error': False, 'array_length_range': [2, 2], 'all_items_keys': ['id', 'description', 'frequency']}, description='Get root causes for pat_001 returns 2'), TestCase(name='match_pattern_existing', tool='match_pattern', params={'message_pattern': 'Timeout waiting for data', 'function': 'BoardReader::processData'}, expected={'json_valid': True, 'error': False}, description='Match pattern against known error signature')]